-- Migration 021: more exam tips: a solving method, keywords, roles, agile, stakeholders, risk,
-- procurement, quality, schedule, governance, value, traps, study plan, mock review, tips for
-- Arabic speakers and exam day. Adds each section once, after the existing ones, and skips any
-- section whose English title already exists. Original text, written for this simulator.
-- No BEGIN/COMMIT here: scripts/migrate.ts wraps every file in one transaction.

INSERT INTO tip_sections (position, title_en, title_ar, items)
SELECT (SELECT coalesce(max(position), 0) FROM tip_sections) + v.ord, v.title_en, v.title_ar, v.items
FROM (VALUES
  (1, $t$A step-by-step method for every question$t$, $t$طريقة ثابتة خطوة بخطوة لكل سؤال$t$, $t$[{"en": "Step 1: read the last sentence and underline the real question (FIRST, NEXT, BEST, MOST, EXCEPT, LEAST).", "ar": "الخطوة 1: اقرأ الجملة الأخيرة وحدّد السؤال الحقيقي (FIRST و NEXT و BEST و MOST و EXCEPT و LEAST)."}, {"en": "Step 2: read the scenario and note three facts: the approach (predictive, agile, hybrid), where the project is in its life cycle, and who is involved.", "ar": "الخطوة 2: اقرأ الموقف وسجّل ثلاث معلومات: النهج (predictive أو agile أو hybrid)، وأين المشروع في دورة حياته، ومن الأطراف المعنية."}, {"en": "Step 3: name the problem in your own words in a few words: conflict, scope change, risk that occurred, unhappy stakeholder, quality defect.", "ar": "الخطوة 3: سمِّ المشكلة بكلماتك في كلمات قليلة: خلاف، تغيير نطاق، خطر وقع، صاحب مصلحة غير راضٍ، عيب جودة."}, {"en": "Step 4: before reading the options, predict what a good project manager would do.", "ar": "الخطوة 4: قبل قراءة الاختيارات، توقّع ما الذي يفعله مدير المشروع الجيد."}, {"en": "Step 5: read all options, even if the first one looks right. Remove the ones that break a rule (escalate first, ignore, act alone, skip the process).", "ar": "الخطوة 5: اقرأ كل الاختيارات حتى لو بدا الأول صحيحًا. استبعد ما يخالف قاعدة (التصعيد أولًا، التجاهل، التصرف منفردًا، تجاوز الإجراء)."}, {"en": "Step 6: compare the last two options against the exact question word. If the question asks FIRST, choose the step that comes earliest in the right order.", "ar": "الخطوة 6: قارن الاختيارين الأخيرين بكلمة السؤال بالضبط. إذا كان السؤال FIRST فاختر الخطوة التي تأتي أولًا في الترتيب الصحيح."}, {"en": "Step 7: answer, flag if unsure, and move on. Do not reread the same question more than twice.", "ar": "الخطوة 7: أجب، وضع علامة إن لم تكن متأكدًا، وأكمل. لا تعد قراءة نفس السؤال أكثر من مرتين."}]$t$::jsonb),
  (2, $t$Keywords and what they usually signal$t$, $t$كلمات مفتاحية وما تشير إليه غالبًا$t$, $t$[{"en": "\"Has occurred\", \"is now\", \"the team reports\": an issue. Use the issue log and act now.", "ar": "«حدث» و«أصبح الآن» و«أبلغ الفريق»: هذه issue. استخدم الـ issue log وتصرف الآن."}, {"en": "\"Might\", \"may\", \"could\", \"is concerned that\": a risk. Use the risk register and plan a response.", "ar": "«قد» و«ربما» و«يمكن» و«يخشى أن»: هذا risk. استخدم سجل المخاطر وخطط للاستجابة."}, {"en": "\"Product owner\", \"sprint\", \"backlog\", \"increment\", \"velocity\": think agile. Changes go to the backlog, not the running sprint.", "ar": "«product owner» و«sprint» و«backlog» و«increment» و«velocity»: فكّر بطريقة agile. التغييرات تذهب للـ backlog لا للـ sprint الجاري."}, {"en": "\"Baseline\", \"change control board\", \"WBS\", \"critical path\": think predictive. Changes need a formal change request.", "ar": "«baseline» و«change control board» و«WBS» و«critical path»: فكّر بطريقة predictive. التغييرات تحتاج طلب تغيير رسمي."}, {"en": "\"New\" anything (new team member, new stakeholder, new regulation, new vendor): the answer is usually to assess or analyze first.", "ar": "أي شيء «جديد» (عضو جديد، صاحب مصلحة جديد، لائحة جديدة، مورّد جديد): الإجابة غالبًا التقييم أو التحليل أولًا."}, {"en": "\"Sponsor is pressing\", \"deadline\", \"urgent\": pressure in the question is a test. The right answer still follows the process, ethics and safety.", "ar": "«الـ sponsor يضغط» و«موعد نهائي» و«عاجل»: الضغط في السؤال اختبار. الإجابة الصحيحة ما زالت تتبع الإجراء والأخلاقيات والسلامة."}, {"en": "\"Team members disagree\", \"tension\", \"argue\": a conflict. Understand the source first, usually in private, then collaborate.", "ar": "«خلاف بين الأعضاء» و«توتر» و«جدال»: هذا خلاف. افهم المصدر أولًا، غالبًا على انفراد، ثم تعاون للحل."}, {"en": "\"Value\", \"benefits\", \"outcomes\", \"customer satisfaction\": the 2026 exam wants you to look beyond delivering on time and on budget.", "ar": "«القيمة» و«الفوائد» و«النتائج» و«رضا العملاء»: امتحان 2026 يريدك أن تنظر أبعد من التسليم في الوقت والميزانية."}]$t$::jsonb),
  (3, $t$Who does what$t$, $t$مين بيعمل إيه$t$, $t$[{"en": "Sponsor: funds the project, champions it, approves the charter and big decisions, and is the escalation point when the project manager has done what they can.", "ar": "الـ Sponsor: يموّل المشروع ويدعمه ويعتمد الـ charter والقرارات الكبيرة، وهو نقطة التصعيد بعد أن يستنفد مدير المشروع ما يستطيع."}, {"en": "Project manager: plans, coordinates, communicates, removes obstacles and is accountable for the project's results. Does not make decisions that belong to others.", "ar": "مدير المشروع: يخطط وينسق ويتواصل ويزيل العوائق، وهو مسؤول عن نتائج المشروع. لا يتخذ قرارات تخص غيره."}, {"en": "Product owner: owns the product backlog and decides its order based on value. Only the product owner changes backlog priorities.", "ar": "الـ Product owner: يملك الـ product backlog ويقرر ترتيبه حسب القيمة. هو وحده من يغيّر أولويات الـ backlog."}, {"en": "Agile team: decides how to do the work and how much it can take into a sprint. Nobody assigns tasks to a self-organizing team.", "ar": "فريق agile: يقرر كيف يُنفذ العمل وكم يأخذ في الـ sprint. لا أحد يوزع المهام على فريق ذاتي التنظيم."}, {"en": "Scrum master or agile coach: a servant leader who facilitates events, coaches the team and removes impediments.", "ar": "الـ Scrum master أو الـ agile coach: قائد خادم ييسّر الفعاليات ويوجّه الفريق ويزيل العوائق."}, {"en": "Change control board: approves or rejects changes to baselines in predictive work. The project manager prepares the impact analysis but does not approve baseline changes alone unless the plan allows it.", "ar": "مجلس ضبط التغيير: يعتمد أو يرفض تغييرات خطوط الأساس في العمل الـ predictive. يُعد مدير المشروع تحليل الأثر لكنه لا يعتمد تغييرات الـ baseline وحده إلا إذا سمحت الخطة."}, {"en": "Functional manager: owns the people and their availability in a matrix organization. Negotiate resources with them, do not go around them.", "ar": "المدير الوظيفي: يملك الأفراد وإتاحتهم في المنظمة المصفوفية. تفاوض معه على الموارد ولا تتجاوزه."}, {"en": "PMO: provides standards, templates, lessons learned and governance support. A good first source when you need organizational knowledge.", "ar": "الـ PMO: يوفر المعايير والقوالب والدروس المستفادة ودعم الحوكمة، وهو مصدر أول جيد عندما تحتاج المعرفة المؤسسية."}]$t$::jsonb),
  (4, $t$Agile and Scrum essentials$t$, $t$أساسيات Agile و Scrum$t$, $t$[{"en": "Sprint planning: the team selects work it can finish and agrees a sprint goal. The product owner explains priorities; the team decides how much.", "ar": "الـ Sprint planning: يختار الفريق العمل الذي يستطيع إنهاءه ويتفق على هدف الـ sprint. الـ product owner يشرح الأولويات والفريق يقرر الكمية."}, {"en": "Daily standup: 15 minutes for the team to coordinate. It is not a status report to the manager, and problems are solved after it.", "ar": "الـ Daily standup: 15 دقيقة لتنسيق الفريق. ليس تقرير حالة للمدير، والمشكلات تُحل بعده."}, {"en": "Sprint review: the team shows the working increment to stakeholders and collects feedback. This is where stakeholders see progress.", "ar": "الـ Sprint review: يعرض الفريق الزيادة العاملة على أصحاب المصلحة ويجمع الملاحظات، وفيه يرى أصحاب المصلحة التقدم."}, {"en": "Retrospective: the team inspects how it worked and picks improvements. It is a safe, blameless meeting for the team.", "ar": "الـ Retrospective: يراجع الفريق طريقة عمله ويختار تحسينات. هو اجتماع آمن وبلا لوم للفريق."}, {"en": "Backlog refinement: the product owner and team clarify, split and estimate upcoming items so they are ready for planning.", "ar": "الـ Backlog refinement: يوضح الـ product owner والفريق العناصر القادمة ويقسمونها ويقدّرونها لتكون جاهزة للتخطيط."}, {"en": "Velocity belongs to one team and is used for that team's forecasting. Never compare velocity between teams or use it to judge people.", "ar": "الـ Velocity خاصة بفريق واحد وتُستخدم لتوقعاته. لا تقارن الـ velocity بين الفرق ولا تستخدمها للحكم على الأفراد."}, {"en": "A spike is a short time-boxed investigation to reduce uncertainty, often used for technical risk.", "ar": "الـ Spike تحقيق قصير محدد بوقت لتقليل عدم اليقين، يُستخدم غالبًا للمخاطر الفنية."}, {"en": "MVP: the smallest release that lets you learn whether you are building the right thing. It is about learning, not about cutting quality.", "ar": "الـ MVP: أصغر إصدار يتيح لك معرفة هل تبني الشيء الصحيح. الهدف التعلم لا التقليل من الجودة."}, {"en": "Kanban limits work in progress to improve flow. When a column is full, the team helps finish work instead of starting more.", "ar": "الـ Kanban يحد من العمل الجاري لتحسين التدفق. عندما يمتلئ عمود، يساعد الفريق في إنهاء العمل بدل بدء المزيد."}]$t$::jsonb),
  (5, $t$Stakeholders and communication$t$, $t$أصحاب المصلحة والتواصل$t$, $t$[{"en": "Identify stakeholders early and keep identifying them throughout the project. The stakeholder register is a living document.", "ar": "حدّد أصحاب المصلحة مبكرًا واستمر في ذلك طوال المشروع. سجل أصحاب المصلحة مستند حي."}, {"en": "Power/interest grid: high power and high interest, manage closely; high power and low interest, keep satisfied; low power and high interest, keep informed; low and low, monitor.", "ar": "شبكة التأثير/الاهتمام: تأثير واهتمام عاليان، أدِره عن قرب؛ تأثير عالٍ واهتمام منخفض، أبقه راضيًا؛ تأثير منخفض واهتمام عالٍ، أبقه مطّلعًا؛ الاثنان منخفضان، راقبه."}, {"en": "Tailor the message to the person: executives want decisions and exceptions, the team wants detail, users want what changes for them.", "ar": "كيّف الرسالة حسب الشخص: التنفيذيون يريدون القرارات والاستثناءات، والفريق يريد التفاصيل، والمستخدمون يريدون ما الذي سيتغير لهم."}, {"en": "Resistance usually has a reason. Listen, understand the concern, and involve the person before trying to persuade.", "ar": "المقاومة غالبًا لها سبب. استمع وافهم القلق وأشرك الشخص قبل محاولة الإقناع."}, {"en": "Face-to-face or live conversation is the richest communication method. Use it for sensitive or complex topics.", "ar": "الحوار المباشر أو الحي هو أغنى أساليب التواصل. استخدمه للموضوعات الحساسة أو المعقدة."}, {"en": "Pull communication (dashboards, shared repositories) suits large audiences; push (emails, reports) suits specific recipients; interactive suits decisions and problem solving.", "ar": "التواصل بالسحب (لوحات المتابعة والمستودعات المشتركة) يناسب الجمهور الكبير، والدفع (البريد والتقارير) يناسب مستلمين محددين، والتفاعلي يناسب القرارات وحل المشكلات."}, {"en": "Communication is not complete until you know it was understood. Build in a feedback loop.", "ar": "التواصل لا يكتمل حتى تتأكد أنه فُهم. ضع دائرة ملاحظات."}]$t$::jsonb),
  (6, $t$Risks, issues and reserves$t$, $t$المخاطر والمشكلات والاحتياطيات$t$, $t$[{"en": "Risk process order: plan, identify, analyze (qualitative first, quantitative when needed), plan responses, implement responses, monitor.", "ar": "ترتيب عملية المخاطر: خطط، حدّد، حلّل (نوعيًا أولًا ثم كميًا عند الحاجة)، خطط الاستجابات، نفّذها، راقب."}, {"en": "Threat responses: avoid, transfer, mitigate, accept, escalate. Opportunity responses: exploit, share, enhance, accept, escalate.", "ar": "استجابات التهديد: التجنب والنقل والتخفيف والقبول والتصعيد. استجابات الفرص: الاستغلال والمشاركة والتعزيز والقبول والتصعيد."}, {"en": "Escalate a risk when it is outside the project's authority or affects the wider organization, then the owner outside the project manages it.", "ar": "صعّد الخطر عندما يكون خارج صلاحيات المشروع أو يؤثر على المؤسسة الأوسع، وعندها يديره المالك خارج المشروع."}, {"en": "Each risk needs an owner who watches its triggers and carries out the response.", "ar": "كل خطر يحتاج مالكًا يراقب مؤشراته ويُنفذ الاستجابة."}, {"en": "A workaround is an unplanned response to a risk that occurred without a plan. Record it and update the risk register afterwards.", "ar": "الـ workaround استجابة غير مخططة لخطر وقع دون خطة. سجّلها وحدّث سجل المخاطر بعدها."}, {"en": "Insurance and fixed-price contracts transfer risk; they do not remove it.", "ar": "التأمين والعقود الثابتة السعر تنقل الخطر ولا تلغيه."}, {"en": "Risk reviews happen regularly, not once. New risks appear, old ones close, and probabilities change.", "ar": "مراجعات المخاطر تتم بانتظام وليس مرة واحدة. تظهر مخاطر جديدة وتُغلق قديمة وتتغير الاحتمالات."}]$t$::jsonb),
  (7, $t$Procurement and contracts$t$, $t$المشتريات والعقود$t$, $t$[{"en": "Clear, stable scope: fixed price is usually best for the buyer. Unclear scope: cost-reimbursable. Staff or short, open work: time and materials, ideally with a cap.", "ar": "نطاق واضح وثابت: السعر الثابت غالبًا الأفضل للمشتري. نطاق غير واضح: استرداد التكلفة. أفراد أو عمل قصير مفتوح: الوقت والمواد، ويفضل بسقف."}, {"en": "The contract is the reference for every disagreement with a seller. Changes to it are formal and written.", "ar": "العقد هو المرجع في أي خلاف مع البائع، وتعديلاته رسمية ومكتوبة."}, {"en": "Disputes: negotiate first; then use the dispute resolution steps in the contract, such as mediation or arbitration; court is the last option.", "ar": "النزاعات: تفاوض أولًا، ثم استخدم خطوات حل النزاع في العقد مثل الوساطة أو التحكيم، والمحكمة آخر خيار."}, {"en": "Only someone with authority, often procurement, can change a contract. A project manager's verbal agreement with a seller is not a contract change.", "ar": "فقط صاحب الصلاحية، وغالبًا المشتريات، يستطيع تعديل العقد. الاتفاق الشفهي بين مدير المشروع والبائع ليس تعديلًا للعقد."}, {"en": "Close every procurement: confirm terms are met, settle claims and payments, and give formal notice.", "ar": "أغلق كل عملية شراء: تأكد من استيفاء البنود، وسوِّ المطالبات والمدفوعات، وأرسل إشعارًا رسميًا."}, {"en": "Treat sellers as partners. Fair, ethical treatment and clear communication prevent most claims.", "ar": "تعامل مع البائعين كشركاء. المعاملة العادلة الأخلاقية والتواصل الواضح يمنعان معظم المطالبات."}]$t$::jsonb),
  (8, $t$Quality and continuous improvement$t$, $t$الجودة والتحسين المستمر$t$, $t$[{"en": "Quality is planned in, not inspected in. Prevention is cheaper than finding defects later.", "ar": "الجودة تُخطط من البداية ولا تُضاف بالفحص. الوقاية أرخص من اكتشاف العيوب لاحقًا."}, {"en": "Quality assurance checks the process; quality control checks the product.", "ar": "ضمان الجودة يفحص العملية، وضبط الجودة يفحص المنتج."}, {"en": "Grade is a category of features; quality is how well requirements are met. Low grade can be acceptable, low quality is not.", "ar": "الدرجة (grade) فئة من الخصائص، والجودة مدى تحقيق المتطلبات. الدرجة المنخفضة قد تكون مقبولة، أما الجودة المنخفضة فلا."}, {"en": "Gold plating, adding extras the customer did not ask for, is not good quality. Deliver what was agreed.", "ar": "الـ Gold plating، أي إضافة ما لم يطلبه العميل، ليس جودة جيدة. سلّم ما تم الاتفاق عليه."}, {"en": "Know the tools by purpose: Pareto for the biggest causes, fishbone for possible causes, control chart for process stability, scatter diagram for relationships.", "ar": "اعرف الأدوات حسب الغرض: باريتو لأكبر الأسباب، عظمة السمكة للأسباب المحتملة، مخطط التحكم لاستقرار العملية، مخطط الانتشار للعلاقات."}, {"en": "Rule of seven: seven points in a row on one side of the mean signal a problem even inside the control limits.", "ar": "قاعدة السبعة: سبع نقاط متتالية في جانب واحد من المتوسط تشير لمشكلة حتى لو داخل حدود التحكم."}]$t$::jsonb),
  (9, $t$Schedule and estimating$t$, $t$الجدول والتقدير$t$, $t$[{"en": "The critical path is the longest path and has zero float. Delays on it delay the project.", "ar": "المسار الحرج هو أطول مسار وليس فيه float. أي تأخير عليه يؤخر المشروع."}, {"en": "Total float = late start − early start. Free float is what an activity can slip without delaying the next activity.", "ar": "الـ Total float = البداية المتأخرة − البداية المبكرة. والـ free float هو ما يمكن أن يتأخره نشاط دون تأخير النشاط التالي."}, {"en": "Analogous estimating is fast and early; parametric uses a rate per unit; bottom-up is the most accurate but needs detail; three-point handles uncertainty.", "ar": "التقدير التناظري سريع ومبكر، والبارامتري يستخدم معدلًا لكل وحدة، ومن أسفل لأعلى هو الأدق لكنه يحتاج تفاصيل، والثلاثي النقاط يعالج عدم اليقين."}, {"en": "Three-point: triangular = (O + M + P) ÷ 3; beta/PERT = (O + 4M + P) ÷ 6.", "ar": "الثلاثي النقاط: المثلثي = (O + M + P) ÷ 3، و beta/PERT = (O + 4M + P) ÷ 6."}, {"en": "Resource leveling can lengthen the schedule; resource smoothing keeps the end date and uses only float.", "ar": "تسوية الموارد قد تطيل الجدول، أما تنعيم الموارد فيحافظ على تاريخ النهاية ويستخدم الـ float فقط."}, {"en": "In agile, the team estimates in story points; relative size matters more than hours.", "ar": "في agile يقدّر الفريق بنقاط القصص، والحجم النسبي أهم من الساعات."}]$t$::jsonb),
  (10, $t$Governance, compliance and change (2026 focus)$t$, $t$الحوكمة والامتثال والتغيير (تركيز 2026)$t$, $t$[{"en": "Governance tells you who decides what and when to escalate. Find the thresholds in the governance plan before you act.", "ar": "الحوكمة تحدد من يقرر ماذا ومتى تصعّد. اعرف الحدود في خطة الحوكمة قبل أن تتصرف."}, {"en": "Compliance requirements (safety, security, privacy, regulation, sustainability) are confirmed early, built into the work and measured, not checked once at the end.", "ar": "متطلبات الامتثال (السلامة والأمن والخصوصية واللوائح والاستدامة) تُؤكد مبكرًا وتُبنى في العمل وتُقاس، لا تُفحص مرة واحدة في النهاية."}, {"en": "Noncompliance is never the answer to schedule pressure. Find another way to recover time.", "ar": "عدم الامتثال ليس إجابة أبدًا لضغط الجدول. ابحث عن طريقة أخرى لتعويض الوقت."}, {"en": "Change control order: document, analyze impact, decide (CCB or product owner), communicate, implement, update documents.", "ar": "ترتيب ضبط التغيير: وثّق، حلّل الأثر، قرّر (المجلس أو الـ product owner)، أبلغ، نفّذ، حدّث المستندات."}, {"en": "External changes such as new regulations, technology, markets or geopolitics are assessed for their impact on scope or backlog, then handled through risk or change processes.", "ar": "التغييرات الخارجية مثل اللوائح الجديدة والتقنية والأسواق والجغرافيا السياسية تُقيَّم من حيث أثرها على النطاق أو الـ backlog، ثم تُعالج عبر عمليات المخاطر أو التغيير."}, {"en": "Organizational change needs attention to culture and people: assess readiness, explain why, train and support.", "ar": "التغيير التنظيمي يحتاج اهتمامًا بالثقافة والأفراد: قيّم الجاهزية، واشرح السبب، ودرّب وادعم."}]$t$::jsonb),
  (11, $t$Value, benefits and closure$t$, $t$القيمة والفوائد والإغلاق$t$, $t$[{"en": "A project succeeds when it delivers value worth the effort and cost, not only when it finishes on time and budget.", "ar": "ينجح المشروع عندما يحقق قيمة تستحق الجهد والتكلفة، لا فقط عندما ينتهي في الوقت والميزانية."}, {"en": "Deliver value early and incrementally when you can; it brings feedback and reduces risk.", "ar": "حقق القيمة مبكرًا وتدريجيًا عندما تستطيع، فذلك يجلب الملاحظات ويقلل المخاطر."}, {"en": "Benefits are often realized after the project. Make sure there is a plan, an owner and measures to track them.", "ar": "الفوائد كثيرًا ما تتحقق بعد المشروع. تأكد من وجود خطة ومالك ومقاييس لمتابعتها."}, {"en": "Closure order: formal acceptance, transition to operations, final lessons learned, close contracts and finances, release resources, archive.", "ar": "ترتيب الإغلاق: القبول الرسمي، الانتقال للعمليات، الدروس المستفادة النهائية، إغلاق العقود والمالية، إطلاق الموارد، الأرشفة."}, {"en": "A cancelled project is still closed formally, with the reason and status documented.", "ar": "المشروع الملغى يُغلق رسميًا أيضًا مع توثيق السبب والحالة."}]$t$::jsonb),
  (12, $t$Common traps$t$, $t$فخاخ شائعة$t$, $t$[{"en": "The answer that fixes the problem fastest is often wrong if it skips understanding the cause.", "ar": "الإجابة التي تحل المشكلة بأسرع شكل غالبًا خاطئة إذا تجاوزت فهم السبب."}, {"en": "\"Tell the sponsor\" or \"escalate\" is rarely the first step. Use your own authority and the team first.", "ar": "«أبلغ الـ sponsor» أو «صعّد» نادرًا ما تكون الخطوة الأولى. استخدم صلاحياتك والفريق أولًا."}, {"en": "\"Update the plan\" is not the first step for a change; analyze and approve first.", "ar": "«حدّث الخطة» ليست الخطوة الأولى لأي تغيير؛ حلّل واعتمد أولًا."}, {"en": "Answers where the project manager does the team's work, assigns tasks in agile, or reorders the backlog are usually wrong.", "ar": "الإجابات التي يقوم فيها مدير المشروع بعمل الفريق أو يوزع المهام في agile أو يعيد ترتيب الـ backlog غالبًا خاطئة."}, {"en": "Answers that blame, punish or publicly correct people are almost never right.", "ar": "الإجابات التي تلوم أو تعاقب أو تصحح الأشخاص علنًا تكاد لا تكون صحيحة أبدًا."}, {"en": "Two options can both be true statements. Choose the one that answers the question asked, in the situation described.", "ar": "قد يكون اختياران كلاهما عبارة صحيحة. اختر الذي يجيب عن السؤال المطروح في الموقف الموصوف."}, {"en": "Do not bring your own company's habits into the answer. Answer as the ideal process expects.", "ar": "لا تُدخل عادات شركتك في الإجابة. أجب كما يتوقع الإجراء المثالي."}]$t$::jsonb),
  (13, $t$A study plan and how to use this simulator$t$, $t$خطة مذاكرة وطريقة استخدام المحاكي$t$, $t$[{"en": "Weeks 1–2: read the exam content outline and learn the main concepts for each domain. Use practice mode by domain after each topic.", "ar": "الأسبوعان 1–2: اقرأ مخطط محتوى الامتحان وتعلم المفاهيم الأساسية لكل مجال. استخدم وضع التدريب حسب المجال بعد كل موضوع."}, {"en": "Weeks 3–4: practice mixed questions daily and read every explanation, including why the wrong options are wrong.", "ar": "الأسبوعان 3–4: تدرّب يوميًا على أسئلة مختلطة واقرأ كل شرح، بما فيه لماذا الاختيارات الخاطئة خاطئة."}, {"en": "Weeks 5–6: focus practice on your weakest tasks and approaches, using the simulator's domain and approach filters.", "ar": "الأسبوعان 5–6: ركّز التدريب على أضعف المهام والأساليب لديك باستخدام فلاتر المجال والنهج في المحاكي."}, {"en": "Weeks 7–8: take full timed mock exams, at least two, and review them fully on the next day.", "ar": "الأسبوعان 7–8: أدِّ اختبارات تجريبية كاملة بالتوقيت، اثنين على الأقل، وراجعها كاملة في اليوم التالي."}, {"en": "Use the Arabic toggle to check that you understood a question, then answer in English: the real exam is read in English unless you choose a language aid.", "ar": "استخدم زر العربي للتأكد من فهمك للسؤال، ثم أجب بالإنجليزي: الامتحان الحقيقي يُقرأ بالإنجليزي ما لم تختر مساعدة لغوية."}, {"en": "Bookmark questions you got right by luck. They show gaps as much as wrong answers do.", "ar": "ضع علامة على الأسئلة التي أصبت فيها بالحظ؛ فهي تكشف الفجوات مثل الإجابات الخاطئة."}]$t$::jsonb),
  (14, $t$How to review a mock exam$t$, $t$طريقة مراجعة الاختبار التجريبي$t$, $t$[{"en": "Review every question, not only the wrong ones. Check that your reason for the right answer matches the explanation.", "ar": "راجع كل سؤال لا الخاطئ فقط. تأكد أن سببك في الإجابة الصحيحة يطابق الشرح."}, {"en": "For each wrong answer, write one line: what you chose, why it was wrong, and the rule you will remember.", "ar": "لكل إجابة خاطئة اكتب سطرًا واحدًا: ماذا اخترت، ولماذا كان خطأ، والقاعدة التي ستتذكرها."}, {"en": "Group mistakes by type: misread the question, did not know the concept, fell for a trap, ran out of time. Fix the biggest group first.", "ar": "صنّف الأخطاء حسب النوع: قراءة خاطئة للسؤال، عدم معرفة المفهوم، الوقوع في فخ، نفاد الوقت. عالج أكبر مجموعة أولًا."}, {"en": "Look at your score by domain and approach, not only the total. A good total can hide one weak domain.", "ar": "انظر إلى نتيجتك حسب المجال والنهج لا الإجمالي فقط. الإجمالي الجيد قد يخفي مجالًا ضعيفًا."}, {"en": "Do not retake the same mock right away; you will remember answers instead of reasoning. Practice the weak areas first.", "ar": "لا تُعد نفس الاختبار مباشرة، لأنك ستتذكر الإجابات بدل التفكير. تدرّب على النقاط الضعيفة أولًا."}]$t$::jsonb),
  (15, $t$Tips for Arabic speakers$t$, $t$نصائح للمتحدثين بالعربية$t$, $t$[{"en": "Learn the key terms in English as they appear in questions (issue, risk, baseline, backlog, stakeholder). Translating them in your head slows you down.", "ar": "تعلّم المصطلحات الأساسية بالإنجليزي كما تظهر في الأسئلة (issue و risk و baseline و backlog و stakeholder). ترجمتها في ذهنك تبطئك."}, {"en": "Watch small words that change meaning: NOT, EXCEPT, LEAST, FIRST, NEXT, BEST.", "ar": "انتبه للكلمات الصغيرة التي تغيّر المعنى: NOT و EXCEPT و LEAST و FIRST و NEXT و BEST."}, {"en": "Long sentences hide the question. Split them: who, what happened, what is being asked.", "ar": "الجمل الطويلة تخفي السؤال. قسّمها: من؟ ماذا حدث؟ ما المطلوب؟"}, {"en": "Practice reading speed: aim to read a scenario once, carefully, rather than skimming it three times.", "ar": "تدرّب على سرعة القراءة: اهدف لقراءة الموقف مرة واحدة بعناية بدل تصفحه ثلاث مرات."}, {"en": "PMI offers language aids for some languages. Check PMI's current list when you book the exam.", "ar": "تقدم PMI مساعدات لغوية لبعض اللغات. راجع القائمة الحالية لدى PMI عند حجز الامتحان."}]$t$::jsonb),
  (16, $t$Before and during exam day$t$, $t$قبل يوم الامتحان وأثناءه$t$, $t$[{"en": "Check PMI's current rules for identification, breaks and the testing environment before exam day; they can change.", "ar": "راجع قواعد PMI الحالية للهوية والاستراحات وبيئة الاختبار قبل يوم الامتحان، لأنها قد تتغير."}, {"en": "Under the current format, once you review a section and start a break, you cannot return to that section. Finish your flagged questions before the break.", "ar": "في الشكل الحالي، بمجرد مراجعة قسم وبدء الاستراحة لا يمكنك العودة إليه. أنهِ الأسئلة المعلَّمة قبل الاستراحة."}, {"en": "Sleep well the night before; do not study new topics on the last day.", "ar": "نم جيدًا في الليلة السابقة، ولا تذاكر موضوعات جديدة في اليوم الأخير."}, {"en": "If a question shakes your confidence, take a breath, flag it and move on. One hard question does not decide the result.", "ar": "إذا هزّ سؤال ثقتك، خذ نفسًا وضع علامة وأكمل. سؤال صعب واحد لا يحدد النتيجة."}, {"en": "Never leave a question blank; there is no penalty for a wrong answer.", "ar": "لا تترك سؤالًا دون إجابة، فلا توجد عقوبة على الإجابة الخاطئة."}]$t$::jsonb)
) AS v(ord, title_en, title_ar, items)
WHERE NOT EXISTS (SELECT 1 FROM tip_sections t WHERE t.title_en = v.title_en);
